from __future__ import annotations

from .models import FeedEdge, PrintedFace, PrinterProfile


def build_refeed_instruction(face: str, edge: str) -> str:
    """Preserve the instruction format generated by existing GUI calibrations."""
    face_text = {
        "up": "la cara ya impresa hacia arriba",
        "down": "la cara ya impresa hacia abajo",
    }[face]
    edge_text = {
        "top": "el borde superior entrando primero",
        "bottom": "el borde inferior entrando primero",
    }[edge]
    return f"Coloca el bloque con {face_text} y {edge_text}."


def _legacy_orientation(instruction: str) -> tuple[PrintedFace, FeedEdge] | None:
    """Recognize only exact GUI-generated instructions; never guess orientation."""
    for face in PrintedFace:
        for edge in FeedEdge:
            if instruction.strip() == build_refeed_instruction(face.value, edge.value):
                return face, edge
    return None


def resolve_refeed_orientation(
    profile: PrinterProfile,
) -> tuple[PrintedFace, FeedEdge] | None:
    """Use only persisted calibration or an exact old GUI instruction."""
    if profile.printed_face is not None and profile.feed_edge is not None:
        return profile.printed_face, profile.feed_edge
    return _legacy_orientation(profile.refeed_instruction)


def refeed_guide_text(profile: PrinterProfile, sheet_count: int) -> str:
    """Explain and diagram how to physically reinsert the printed sheet stack."""
    if sheet_count < 1:
        raise ValueError("sheet_count must be positive")

    lines = [
        "GUÍA PARA VOLVER A COLOCAR EL PAPEL",
        "",
        f"Primera pasada completada: {sheet_count} hoja(s).",
        "Espera a que todas las hojas hayan salido por completo.",
        "Mantén el bloque en el mismo orden; no reordenes hojas individualmente.",
        "",
    ]

    orientation = resolve_refeed_orientation(profile)

    if orientation is None:
        lines.extend(
            [
                "No hay un dibujo verificado para esta calibración antigua.",
                "Usa la instrucción que ya estaba guardada:",
                profile.refeed_instruction,
                "",
                "Para obtener una guía visual, vuelve a configurar esta impresora",
                "y comprueba qué cara queda arriba y qué borde entra primero.",
            ]
        )
    else:
        face, edge = orientation
        visible_face = (
            "CARA YA IMPRESA VISIBLE"
            if face is PrintedFace.UP
            else "CARA NO IMPRESA VISIBLE"
        )
        entrance_edge = (
            "BORDE SUPERIOR" if edge is FeedEdge.TOP else "BORDE INFERIOR"
        )
        opposite_edge = (
            "BORDE INFERIOR" if edge is FeedEdge.TOP else "BORDE SUPERIOR"
        )
        face_text = "ARRIBA" if face is PrintedFace.UP else "ABAJO"
        lines.extend(
            [
                "VISTA DESDE ARRIBA DE LA BANDEJA DE ENTRADA",
                "",
                "          [ ENTRADA A LA IMPRESORA ]",
                "                      ↑",
                f"          {entrance_edge} ENTRA PRIMERO",
                "          ┌──────────────────────────┐",
                f"          │{visible_face.center(26)}│",
                "          │                          │",
                "          │     BLOQUE COMPLETO      │",
                "          └──────────────────────────┘",
                f"          {opposite_edge} queda hacia ti",
                "",
                f"Cara ya impresa: {face_text}.",
                f"Borde que entra primero: {entrance_edge}.",
                "Comprueba la orientación del bloque antes de introducirlo.",
                "",
                f"Instrucción guardada: {profile.refeed_instruction}",
            ]
        )

    lines.extend(
        [
            "",
            "Ajusta las guías de papel sin apretarlo.",
            "Continúa solo después de colocar el bloque completo.",
            "Si algo no coincide con tu prueba física, cancela y revisa",
            "la configuración de la impresora.",
        ]
    )
    return "\n".join(lines)
